<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import DOMPurify from 'dompurify';
 import {ResourceServices,resourceRef,cellText,updateCell,previewDocument,type CompanyResource} from './resource-services';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;export let resource:CompanyResource;
 export let verifiedEmailActions:string[]=[];
 const dispatch=createEventDispatcher();let service:ResourceServices|null=null,ref:CompanyResource,snapshot:any=null,draft:any=null,revision=0,title='',error='',notice='',loading=true,busy=false,conflict=false,canEdit=false,editing=false;
 let sheetId='',rowStart=0,columnStart=0,emailPreview='',review:any=null,approved:any=null,confirmed=false,actions:string[]=[],mounted=false,seen='',seenSignal:AbortSignal,detach=()=>{},timer:ReturnType<typeof setInterval>,checking=false,root:HTMLElement;
 $: dirty=!!draft;
 $: if(mounted)dispatch('dirty',{dirty});
 $: workbook=draft||snapshot?.value;
 $: sheet=ref?.kind==='sheet'&&workbook?.sheets?.[sheetId];
 $: rowCount=sheet?.rowCount??100;$: columnCount=sheet?.columnCount??26;
 $: rowIndexes=Array.from({length:Math.min(30,Math.max(0,rowCount-rowStart))},(_,i)=>i+rowStart);
 $: columnIndexes=Array.from({length:Math.min(10,Math.max(0,columnCount-columnStart))},(_,i)=>i+columnStart);
 const columnName=(n:number)=>{let name='';for(n++;n;n=Math.floor((n-1)/26))name=String.fromCharCode(65+(n-1)%26)+name;return name;};
 function clear(){service?.close();service=null;snapshot=null;draft=null;revision=0;title='';emailPreview='';review=null;approved=null;confirmed=false;actions=[];canEdit=false;editing=false;busy=false;checking=false;loading=false;dispatch('dirty',{dirty:false});}
 function fail(e:any){if(e.name==='AbortError')return;error=e.message||'The resource is unavailable.';if(e.status===409){conflict=true;error='A newer revision exists. Your edits are kept. Reload and review before saving.';}if([401,403,404].includes(e.status)){clear();dispatch('denied',{status:e.status});}}
 async function load(){const current=service;if(!current)return;loading=true;error='';notice='';try{const [data,manifests,scope]=await Promise.all([current.snapshot(ref),current.discovery(),current.authority()]);if(current!==service)return;current.current();snapshot=data;revision=data.revision;title=data.value.title||data.value.name||data.value.subject||ref.kind;draft=null;conflict=false;editing=false;emailPreview='';review=null;approved=null;confirmed=false;const manifest=manifests.find((m:any)=>m.resourceKinds.includes(ref.kind));canEdit=ref.kind==='sheet'&&manifest?.editable===true&&scope.capabilities.includes('files.manage')&&new TextEncoder().encode(JSON.stringify(data.value)).length<=120000;const advertised=manifest?.workflowBinding?.version==='starli.email.workflow.v1'&&manifest.workflowBinding.route==='/api/v1/companies/{company}/email-studio/{rid}/{operation}'&&Array.isArray(manifest.workflowActions)?manifest.workflowActions:[];actions=['preview','review','approve'].filter(a=>advertised.includes(a)||verifiedEmailActions.includes(a));if(ref.kind==='sheet'){sheetId=data.value.sheetOrder.includes(sheetId)?sheetId:data.value.sheetOrder[0];rowStart=0;columnStart=0;}}catch(e){if(current===service)fail(e);}finally{if(current===service)loading=false;}}
 async function check(){const current=service;if(!current||busy||loading||checking)return;checking=true;try{const fresh=await current.snapshot(ref);if(current!==service)return;current.current();if(fresh.revision!==revision){review=null;approved=null;confirmed=false;emailPreview='';if(draft){conflict=true;notice='A newer saved revision is available.';}else{snapshot=fresh;revision=fresh.revision;title=fresh.value.title||fresh.value.name||fresh.value.subject||ref.kind;if(ref.kind==='sheet'&&!fresh.value.sheetOrder.includes(sheetId))sheetId=fresh.value.sheetOrder[0];}}}catch(e){if(current===service)fail(e);}finally{if(current===service)checking=false;}}
 function change(row:number,column:number,value:string){if(!canEdit||!editing||conflict||busy)return;try{draft=updateCell(workbook,sheetId,row,column,value);error='';notice='Unsaved changes';}catch(e){fail(e);}}
 async function save(){const current=service;if(!current||!draft||busy||conflict)return;busy=true;error='';try{const saved=await current.editSheet(ref,revision,draft);if(current!==service)return;current.current();snapshot=saved;revision=saved.revision;draft=null;editing=false;notice='Workbook version saved.';}catch(e){if(current===service)fail(e);}finally{if(current===service)busy=false;}}
 function reset(){if(dirty&&!confirm('Discard unsaved cell edits and load the latest version?'))return;void load();}
 function close(){if(dirty&&!confirm('Close this resource and discard unsaved edits?'))return;dispatch('close');}
 async function emailAction(operation:'preview'|'review'|'approve'){const current=service;if(!current||busy||!actions.includes(operation)||operation==='approve'&&(!review||!confirmed))return;busy=true;error='';try{const value=await current.email(ref,operation,revision,actions,review);if(current!==service)return;current.current();if(operation==='preview')emailPreview=previewDocument(value.previewHtml,(html,options)=>DOMPurify.sanitize(html,options));if(operation==='review'){review=value;approved=null;confirmed=false;}if(operation==='approve'){approved=value;notice='Approval recorded for this exact revision. No email was sent.';}}catch(e){if(current===service)fail(e);}finally{if(current===service)busy=false;}}
 function start(){detach();clear();seen=companyId+'|'+actorId+'|'+resource?.ownerId+'|'+resource?.kind+'|'+resource?.id;seenSignal=accessSignal;error='';try{ref=resourceRef(companyId,resource);service=new ResourceServices(companyId,actorId,accessSignal);const signal=accessSignal;const abort=()=>{clear();dispatch('denied',{status:403});};signal.addEventListener('abort',abort,{once:true});detach=()=>signal.removeEventListener('abort',abort);void load();}catch(e){fail(e);}}
 $: if(mounted&&(seen!==companyId+'|'+actorId+'|'+resource?.ownerId+'|'+resource?.kind+'|'+resource?.id||seenSignal!==accessSignal))start();
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){clear();dispatch('denied',{status:401});}}
 function shortcut(e:KeyboardEvent){if(root?.contains(e.target as Node)&&ref?.kind==='sheet'&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();void save();}}
 onMount(()=>{mounted=true;timer=setInterval(()=>{if(!document.hidden)void check();},4000);});onDestroy(()=>{mounted=false;clearInterval(timer);detach();clear();});
</script>
<svelte:window on:storage={session} on:keydown={shortcut}/>
<section class="pane" bind:this={root} aria-label="Company resource"><header><div><small>{ref?.kind||'Company resource'} · {revision?'Revision '+revision:''}</small><h2>{title||'Opening resource…'}</h2></div><button class="close" aria-label="Close resource" on:click={close}>×</button></header>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
{#if loading}<p class="empty" role="status">Loading the authorized resource…</p>{:else if snapshot}<div class="content">{#if ref.kind==='sheet'}<div class="toolbar"><select aria-label="Workbook sheet" bind:value={sheetId} on:change={()=>{rowStart=0;columnStart=0;}}>{#each workbook.sheetOrder as id}<option value={id}>{workbook.sheets[id].name}</option>{/each}</select><div>{#if canEdit}<button disabled={busy||conflict} on:click={()=>editing=!editing}>{editing?'Finish editing':'Edit cells'}</button><button class="primary" disabled={busy||!dirty||conflict} on:click={save}>{busy?'Saving…':'Save version'}</button>{:else}<span class="hint">Read-only workbook</span>{/if}<button disabled={busy} on:click={reset}>Reload</button></div></div><p class="hint">Stored values and formulas. This pane does not recalculate formulas or run external references.</p>{#if conflict}<p class="error">Your draft is retained. Reload to review the current version before saving.</p>{/if}<div class="grid-scroll"><table><thead><tr><th></th>{#each columnIndexes as column}<th>{columnName(column)}</th>{/each}</tr></thead><tbody>{#each rowIndexes as row}<tr><th>{row+1}</th>{#each columnIndexes as column}<td>{#if editing&&canEdit}<input aria-label={columnName(column)+(row+1)} value={cellText(sheet?.cellData?.[row]?.[column])} disabled={busy||conflict} on:change={e=>change(row,column,e.currentTarget.value)}/>{:else}<span>{cellText(sheet?.cellData?.[row]?.[column])}</span>{/if}</td>{/each}</tr>{/each}</tbody></table></div><div class="paging"><button disabled={rowStart===0} on:click={()=>rowStart=Math.max(0,rowStart-30)}>Previous rows</button><span>{rowStart+1}–{Math.min(rowStart+30,rowCount)} / {rowCount}</span><button disabled={rowStart+30>=rowCount} on:click={()=>rowStart+=30}>Next rows</button><button disabled={columnStart===0} on:click={()=>columnStart=Math.max(0,columnStart-10)}>← Columns</button><button disabled={columnStart+10>=columnCount} on:click={()=>columnStart+=10}>Columns →</button></div>
{:else if ref.kind==='email'}<div class="email-meta"><h3>{snapshot.value.subject||'Email draft'}</h3><dl><dt>To</dt><dd>{Array.isArray(snapshot.value.to)?snapshot.value.to.join(', '):'Unavailable'}</dd><dt>Cc</dt><dd>{Array.isArray(snapshot.value.cc)?snapshot.value.cc.join(', '):''}</dd><dt>Bcc</dt><dd>{Array.isArray(snapshot.value.bcc)?snapshot.value.bcc.join(', '):''}</dd></dl></div><details><summary>Saved email JSON · Read-only</summary><pre>{JSON.stringify(snapshot.value,null,2)}</pre></details>{#if actions.length}<div class="toolbar"><div>{#if actions.includes('preview')}<button disabled={busy} on:click={()=>emailAction('preview')}>Preview saved email</button>{/if}{#if actions.includes('review')}<button disabled={busy} on:click={()=>emailAction('review')}>Review exact revision</button>{/if}</div></div>{:else}<p class="hint">Preview and approval are not advertised by the active email service. Saved content is read-only here.</p>{/if}{#if emailPreview}<iframe title="Saved email preview" sandbox="" referrerpolicy="no-referrer" srcdoc={emailPreview}/>{/if}{#if review}<section class="review"><h3>Review revision {review.revision}</h3><dl><dt>From</dt><dd>{review.identity.name} &lt;{review.identity.address}&gt;</dd><dt>To</dt><dd>{review.document.to?.join(', ')}</dd><dt>Cc</dt><dd>{review.document.cc?.join(', ')}</dd><dt>Bcc</dt><dd>{review.document.bcc?.join(', ')}</dd><dt>Subject</dt><dd>{review.document.subject}</dd></dl><p class="hint">Attachments and saved images</p><ul>{#each review.bound as asset}<li>{asset.filename} · {asset.sha256}</li>{/each}</ul><pre>{JSON.stringify(review.document,null,2)}</pre>{#if actions.includes('approve')}<label class="approval"><input type="checkbox" bind:checked={confirmed} disabled={busy||!!approved}/>I approve the displayed sender, recipients, content and attachments for revision {review.revision}.</label><button class="primary" disabled={!confirmed||busy||!!approved} on:click={()=>emailAction('approve')}>Approve exact revision</button>{/if}{#if approved}<p class="notice">Approved. No email was sent.</p>{/if}</section>{/if}
{:else}<h3>{snapshot.value.title||ref.kind}</h3><p class="body">{snapshot.value.body||'No details added.'}</p><p class="hint">This resource is read-only in this pane.</p>{/if}</div>{:else}<p class="empty">Resource access is unavailable.</p>{/if}</section>
<style>.pane{height:100%;width:100%;min-width:0;display:flex;flex-direction:column;background:#fff;color:#17243f;font-size:12px;overflow:hidden}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:19px 22px;border-bottom:1px solid #e6ebf4}header>div{min-width:0}header small{font-size:10px;color:#a2adbf;text-transform:capitalize}h2{font-size:14px;font-weight:550;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:4px 0 0}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.close{border:0;background:none;font-size:22px;color:#a0adc2}.content{padding:22px;overflow:auto;flex:1;min-height:0}h3{font-size:14px;font-weight:550;margin:0 0 13px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px;flex-wrap:wrap}.toolbar>div{display:flex;gap:8px;flex-wrap:wrap}.toolbar button,.paging button{background:none;border:1px solid #e6ebf4;border-radius:6px;padding:6px 9px;color:#7c8eab;font-size:10px}.toolbar select{border:1px solid #e6ebf4;background:#f6f8fc;border-radius:7px;padding:7px 10px;font-size:11px;max-width:220px}.primary{background:#3466f6!important;border:0!important;border-radius:7px;padding:8px 12px;color:white!important;font-size:11px}.hint{font-size:10px;color:#9ba7ba;line-height:1.7;margin:12px 0}.error{font-size:11px;line-height:1.7;color:#ad4b52;padding:0 22px;overflow-wrap:anywhere}.notice{font-size:11px;line-height:1.7;color:#688e7b;padding:0 22px}.empty{font-size:12px;text-align:center;color:#9ba7ba;padding:35px 22px}.grid-scroll{overflow:auto;border:1px solid #e6ebf4;border-radius:8px;max-height:65dvh}table{border-collapse:collapse;min-width:100%;font-size:11px}th,td{border-right:1px solid #e9edf5;border-bottom:1px solid #e9edf5;height:29px;min-width:100px;max-width:220px;padding:0}th{background:#f6f8fc;color:#9aa7bc;font-size:10px;font-weight:500;position:sticky;top:0}th:first-child{min-width:35px;left:0}td span{display:block;white-space:pre;overflow:hidden;text-overflow:ellipsis;padding:6px 8px;max-width:220px}td input{border:0;background:#fbfcff;color:#17243f;width:100%;min-width:100px;height:28px;padding:4px 7px}.paging{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:13px 0;font-size:9px;color:#9aa7bc}.paging span{padding:0 4px}.body{white-space:pre-wrap;line-height:1.8;font-size:12px;color:#73829a}dl{display:grid;grid-template-columns:55px 1fr;gap:8px;font-size:11px;margin:18px 0}dt{color:#a2aec0}dd{margin:0;overflow-wrap:anywhere}details{border:1px solid #e6ebf4;border-radius:8px;padding:12px;margin:20px 0}summary{cursor:pointer;font-size:11px;color:#8595af}pre{font-family:ui-monospace,monospace;font-size:10px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fc;padding:13px;border-radius:7px;max-height:350px;overflow:auto;margin-top:12px}iframe{width:100%;height:560px;border:1px solid #e6ebf4;border-radius:8px;background:white;margin:15px 0}.review{border-top:1px solid #e6ebf4;padding-top:22px;margin-top:22px}.review li{font-size:10px;color:#8d9db5;overflow-wrap:anywhere;padding:3px 0}.approval{display:flex;gap:8px;align-items:flex-start;font-size:11px;line-height:1.7;color:#7e8da7;margin:18px 0}.approval input{margin-top:4px}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #789bff;outline-offset:2px}@media(max-width:700px){.content{padding:18px}header{padding:16px 18px}.toolbar{align-items:flex-start}.grid-scroll{max-height:58dvh}}</style>
